import type { JSX } from 'react';
import React, { Dispatch, SetStateAction } from 'react';
import { useTranslation } from 'react-i18next';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

interface ScaleSelectorProps {
  selectedKey?: string;
  scales: string[];
  scale?: string;
  setScale: Dispatch<SetStateAction<string | undefined>>;
}
export const ScaleSelector = ({
  selectedKey,
  scales,
  scale,
  setScale,
}: ScaleSelectorProps): JSX.Element => {
  const { t } = useTranslation(['scale']);
  const label = t('scale:title', scale ? { context: 'selected', scale } : undefined);
  return !selectedKey || scales.length < 2 ? (
    <Button
      variant="ghost"
      disabled
      className="capitalize text-slate-700 bg-gray-200 hover:bg-gray-200 w-48"
    >
      {label}
    </Button>
  ) : (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" className="capitalize bg-white w-48">
          {label}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent>
        <DropdownMenuItem
          key="none"
          disabled={scale === undefined}
          onClick={() => setScale(undefined)}
        >
          {t('scale:none')}
        </DropdownMenuItem>
        {scales.map((option) => (
          <DropdownMenuItem
            key={option}
            disabled={option === scale}
            onClick={() => setScale(option)}
          >
            {option}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
};
